21	```java
22	interface ReadingListener {
23	    void onReading(SensorReading reading);
24	}
25	
26	final class WeatherStation {
27	    private final List<ReadingListener> listeners;           // received from outside
28	    WeatherStation(List<ReadingListener> listeners) { this.listeners = List.copyOf(listeners); }
29	
