1	package hotel.reservations;
2	
3	import hotel.rooms.Room;
4	import hotel.rooms.Rooms;
5	import java.math.BigDecimal;
6	import java.util.List;
7	
8	/** The life of a reservation: created, confirmed (paid), checked in, checked out, or cancelled. */
9	public final class ReservationService {
10	
11	    private final Rooms rooms;
12	    private final ReservationStore store;
13	    private final PriceCalculator priceCalculator;
14	    private final List<ReservationListener> listeners;
15	
16	    public ReservationService(
17	            Rooms rooms, ReservationStore store, PriceCalculator priceCalculator, List<ReservationListener> listeners) {
18	        this.rooms = rooms;
19	        this.store = store;
20	        this.priceCalculator = priceCalculator;
21	        this.listeners = listeners;
22	    }
23	
24	    public synchronized Reservation create(NewReservation request) {
25	        if (!request.checkOut().isAfter(request.checkIn())) {
26	            throw new HotelException(ErrorCode.INVALID_REQUEST, "check-out must be after check-in");
27	        }
28	        if (request.guests() < 1) {
29	            throw new HotelException(ErrorCode.INVALID_REQUEST, "a reservation needs at least one guest");
30	        }
31	        Room room = rooms.find(request.roomNumber())
32	                .orElseThrow(() -> new HotelException(
33	                        ErrorCode.ROOM_NOT_FOUND, "room " + request.roomNumber() + " does not exist"));
34	        if (request.guests() > room.capacity()) {
35	            throw new HotelException(
36	                    ErrorCode.CAPACITY_EXCEEDED,
37	                    "room " + room.number() + " takes at most " + room.capacity() + " guests");
38	        }
39	        if (store.isRoomTaken(room.number(), request.checkIn(), request.checkOut())) {
40	            throw new HotelException(
41	                    ErrorCode.ROOM_UNAVAILABLE, "room " + room.number() + " is taken on some of those nights");
42	        }
43	        Price price = priceCalculator.calculate(room, request.checkIn(), request.checkOut(), request.ratePlan());
44	        return store.add(request, price);
45	    }
46	
47	    public Reservation find(long reservationId) {
48	        return store.find(reservationId)
49	                .orElseThrow(() -> new HotelException(
50	                        ErrorCode.RESERVATION_NOT_FOUND, "reservation " + reservationId + " does not exist"));
51	    }
52	
53	    /** The guest paid: the reservation is confirmed and listeners are notified. */
54	    public synchronized Reservation confirm(long reservationId) {
55	        Reservation reservation = find(reservationId);
56	        if (reservation.status() != ReservationStatus.PENDING) {
57	            throw notAllowed(reservation, "confirm");
58	        }
59	        reservation.confirmPayment();
60	        store.update(reservation);
61	        Room room = roomOf(reservation);
62	        for (ReservationListener listener : listeners) {
63	            listener.onConfirmation(reservation, room);
64	        }
65	        return reservation;
66	    }
67	
68	    /**
69	     * Cancelling before the stay starts. What was paid comes back according to the rate plan (a pending
70	     * reservation was never paid, so nothing comes back). Listeners are notified only if the reservation was confirmed.
71	     */
72	    public synchronized Reservation cancel(long reservationId) {
73	        Reservation reservation = find(reservationId);
74	        if (reservation.status() != ReservationStatus.PENDING
75	                && reservation.status() != ReservationStatus.CONFIRMED) {
76	            throw notAllowed(reservation, "cancel");
77	        }
78	        boolean wasConfirmed = reservation.status() == ReservationStatus.CONFIRMED;
79	        BigDecimal refund = switch (reservation.ratePlan()) {
80	            case STANDARD -> reservation.amountPaid();
81	            case NON_REFUNDABLE -> PriceCalculator.cents(BigDecimal.ZERO);
82	        };
83	        reservation.cancel(refund);
84	        store.update(reservation);
85	        if (wasConfirmed) {
86	            Room room = roomOf(reservation);
87	            for (ReservationListener listener : listeners) {
88	                listener.onCancellation(reservation, room);
89	            }
90	        }
91	        return reservation;
92	    }
93	
94	    public synchronized Reservation checkIn(long reservationId) {
95	        Reservation reservation = find(reservationId);
96	        if (reservation.status() != ReservationStatus.CONFIRMED) {
97	            throw notAllowed(reservation, "check in");
98	        }
99	        reservation.changeStatus(ReservationStatus.CHECKED_IN);
100	        store.update(reservation);
101	        return reservation;
102	    }
103	
104	    /** The guest leaves: the stay is closed and the final receipt is handed over. */
105	    public synchronized ReservationReceipt checkOut(long reservationId) {
106	        Reservation reservation = find(reservationId);
107	        if (reservation.status() != ReservationStatus.CHECKED_IN) {
108	            throw notAllowed(reservation, "check out");
109	        }
110	        reservation.changeStatus(ReservationStatus.CHECKED_OUT);
111	        store.update(reservation);
112	        return new ReservationReceipt(reservation, roomOf(reservation));
113	    }
114	
115	    /** A copy of the receipt, for a guest who lost it. Only paid reservations have one. */
116	    public ReservationReceipt receiptCopy(long reservationId) {
117	        Reservation reservation = find(reservationId);
118	        if (!reservation.isPaid()) {
119	            throw notAllowed(reservation, "issue a receipt for");
120	        }
121	        return new ReservationReceipt(reservation, roomOf(reservation));
122	    }
123	
124	    private Room roomOf(Reservation reservation) {
125	        return rooms.find(reservation.roomNumber()).orElseThrow();
126	    }
127	
128	    private static HotelException notAllowed(Reservation reservation, String operation) {
129	        return new HotelException(
130	                ErrorCode.OPERATION_NOT_ALLOWED,
131	                "cannot " + operation + " reservation " + reservation.id() + " while it is " + reservation.status());
132	    }
133	}
